#import <Foundation/Foundation.h>
#import "../App/AI/Core/TFAIContextProjection.h"
static NSUInteger checks;
static void Check(BOOL ok,NSString *label){checks++;if(!ok){NSLog(@"FAIL %@",label);exit(1);}}
static NSData *Encoded(id value){return [NSJSONSerialization dataWithJSONObject:value options:NSJSONWritingSortedKeys error:nil];}
static NSString *JSONString(id value){return [[NSString alloc]initWithData:Encoded(value) encoding:NSUTF8StringEncoding];}
static NSString *Large(NSUInteger n){return [@"// source line 1234567890\n" stringByPaddingToLength:n withString:@"// source line 1234567890\n" startingAtIndex:0];}
static NSMutableArray *Fixture(NSUInteger count,BOOL legacy){NSMutableArray *m=[NSMutableArray arrayWithObjects:@{@"role":@"system",@"content":@"Keep approvals; project A."},@{@"role":@"user",@"content":@"Fix this project without deleting unrelated files."},nil];for(NSUInteger i=0;i<count;i++){NSString *identifier=[NSString stringWithFormat:@"patch-%lu",(unsigned long)i];[m addObject:@{@"role":@"assistant",@"content":@"Prepare patch only.",@"tool_calls":@[@{@"id":identifier,@"name":@"propose_patch",@"arguments":@{@"edits":@[@{@"path":@"Tweak.xm",@"before":Large(48*1024),@"after":Large(48*1024+1)}]}}]}];NSDictionary *result=legacy?@{@"error":@"Not applied; original text mismatch",@"full_diff":Large(120*1024)}:@{@"proposal_id":identifier,@"edit_count":@1,@"previewStoredLocally":@YES};[m addObject:@{@"role":@"tool",@"tool_call_id":identifier,@"content":JSONString(result)}];}return m;}
static void Pairs(NSArray *messages){NSMutableSet *calls=[NSMutableSet new],*results=[NSMutableSet new];for(NSDictionary *m in messages){for(NSDictionary *c in m[@"tool_calls"])[calls addObject:c[@"id"]];if([m[@"role"] isEqual:@"tool"])[results addObject:m[@"tool_call_id"]];}Check([calls isEqual:results],@"complete tool pairs retained");}
int main(){@autoreleasepool{
 NSArray *schemas=@[TFAIContextProjection.schema];NSMutableArray *input=Fixture(30,NO);NSData *original=Encoded(input);NSDictionary *stats=nil;NSError *error=nil;
 NSArray *out=[TFAIContextProjection project:input schemas:schemas statistics:&stats error:&error];
 Check(out&&!error,@"30 large proposals fit");Pairs(out);Check([original isEqual:Encoded(input)],@"full local transcript and execution arguments unchanged");Check([stats[@"afterTextJSONBytes"] unsignedIntegerValue]<[stats[@"beforeTextJSONBytes"] unsignedIntegerValue]/20,@"more than 95 percent reduction in synthetic patch history");Check([out[0][@"content"] isEqual:input[0][@"content"]]&&[out[1][@"content"] isEqual:input[1][@"content"]],@"system and user instructions preserved verbatim");
 printf("SYNTHETIC_30_PATCHES before=%lu after=%lu bytes reduction=%.2f%%\n",[stats[@"beforeTextJSONBytes"] unsignedLongValue],[stats[@"afterTextJSONBytes"] unsignedLongValue],100.0*(1-[stats[@"afterTextJSONBytes"] doubleValue]/[stats[@"beforeTextJSONBytes"] doubleValue]));
 NSString *all=JSONString(out);Check([all containsString:@"[DYLIX_CONTEXT_OFFLOADED]"]&&[all containsString:@"proposal_id"],@"explicit offload markers and proposal receipts");Check([TFAIContextProjection containsPlaceholder:@{@"edits":@[@{@"after":@"[DYLIX_CONTEXT_OFFLOADED] fake source"}]}],@"nested source placeholder detected before execution");
 Check(![TFAIContextProjection containsPlaceholder:@"NSString *marker = @\"[DYLIX_CONTEXT_OFFLOADED]\";"],@"literal marker constant in real source remains editable");
 NSString *stub=out[2][@"tool_calls"][0][@"arguments"][@"edits"][0][@"before"];Check([TFAIContextProjection containsPlaceholder:[@"// header\n" stringByAppendingString:stub]],@"embedded real offload stub still blocked");
 Check(![TFAIContextProjection containsPlaceholder:@"normal source code"],@"ordinary code unaffected by stub guard");
 NSMutableString *retrieved=[NSMutableString new];NSUInteger offset=0;do{NSDictionary *r=[TFAIContextProjection read:@{@"ref":@"arguments:patch-0",@"offset":@(offset),@"limit":@4096} messages:input error:&error];Check(r!=nil,@"arguments page available");[retrieved appendString:r[@"text"]];if(r[@"next_offset"]==NSNull.null)break;offset=[r[@"next_offset"] unsignedIntegerValue];}while(YES);Check([retrieved isEqual:JSONString(input[2][@"tool_calls"][0][@"arguments"])],@"exact argument reconstruction and valid JSON");
 Check(![TFAIContextProjection read:@{@"ref":@"result:other-session"} messages:input error:&error],@"cross-session unknown references denied");error=nil;
 NSArray *large=Fixture(30,YES);out=[TFAIContextProjection project:large schemas:schemas statistics:&stats error:&error];Check(out!=nil,@"legacy full results fit without enabling project memory");Pairs(out);Check([JSONString(out) containsString:@"Not applied"],@"failure preserved instead of invented success");Check([stats[@"resultsOffloaded"] unsignedIntegerValue]==30,@"large legacy outputs offloaded");
 NSDictionary *r=[TFAIContextProjection read:@{@"ref":@"result:patch-29",@"limit":@4096} messages:large error:&error];Check([r[@"text"] containsString:@"Not applied"],@"full legacy result remains recoverable");
 NSMutableArray *pending=Fixture(1,NO);[pending removeLastObject];out=[TFAIContextProjection project:pending schemas:schemas statistics:nil error:&error];Check([out.lastObject[@"tool_calls"] isEqual:pending.lastObject[@"tool_calls"]],@"pending tool arguments are not rewritten");
 NSArray *blocked=@[@{@"role":@"system",@"content":Large(300*1024)},@{@"role":@"user",@"content":@"Keep me"}];Check(![TFAIContextProjection project:blocked schemas:schemas statistics:nil error:&error]&&error,@"irreducible instructions fail closed without deleting history");
 // Exercise aggregate folding with many moderate-size results, including one user turn.
 NSMutableArray *loop=[NSMutableArray arrayWithObjects:input[0],input[1],nil];for(NSUInteger i=0;i<100;i++){NSString *identifier=[NSString stringWithFormat:@"r-%lu",i];[loop addObject:@{@"role":@"assistant",@"content":@"Inspect",@"tool_calls":@[@{@"id":identifier,@"name":@"read_file",@"arguments":@{@"path":@"Tweak.xm"}}]}];[loop addObject:@{@"role":@"tool",@"tool_call_id":identifier,@"content":Large(8192)}];}out=[TFAIContextProjection project:loop schemas:schemas statistics:&stats error:&error];Check(out&&[stats[@"toolBatchesCollapsed"] unsignedIntegerValue]>0,@"in-loop budget works without eight user turns");Pairs(out);Check([out.lastObject isEqual:loop.lastObject],@"latest observation kept");
 // No local display copies, authorized-directory bookmarks, or base64 token guesses.
 NSDictionary *local=@{@"role":@"user",@"content":@"Hi",@"display":Large(400*1024),@"localAttachmentReferences":@{@"bookmark":Large(400*1024)}};out=[TFAIContextProjection project:@[local] schemas:schemas statistics:&stats error:nil];Check(out.count==1&&!out[0][@"display"]&&!out[0][@"localAttachmentReferences"],@"UI-only metadata excluded from model projection");
 NSArray *unicode=@[@{@"role":@"assistant",@"content":@"A👨‍👩‍👧‍👦中文😀B"}];r=[TFAIContextProjection read:@{@"ref":@"message:0",@"limit":@12} messages:unicode error:nil];Check([r[@"text"] isEqual:@"A👨‍👩‍👧‍👦"],@"pagination does not split composed Unicode");Check(![TFAIContextProjection read:@{@"ref":@"message:0",@"offset":@3} messages:unicode error:nil],@"mid-surrogate offset rejected");
 Check(![TFAIContextProjection project:Fixture(3,NO) schemas:@[] statistics:nil error:nil],@"oversized tools-disabled connection stops instead of making unrecoverable stubs");
 NSArray *small=@[@{@"role":@"user",@"content":@"Keep this request"}];Check([TFAIContextProjection project:small schemas:@[] statistics:nil error:nil]!=nil,@"ordinary chat without tools still works");
 NSMutableArray *duplicate=[input mutableCopy];[duplicate addObject:input[3]];Check(![TFAIContextProjection read:@{@"ref":@"result:patch-0"} messages:duplicate error:nil],@"ambiguous duplicate IDs fail closed");
 NSDictionary *badBudget=nil;Check(![TFAIContextProjection project:small schemas:@[@{@"name":@"huge_schema",@"description":Large(300*1024)}] statistics:&badBudget error:nil]&&[badBudget[@"beforeTextJSONBytes"] unsignedIntegerValue]>256*1024,@"schema cost is part of the context budget");
 NSDictionary *partial=@{@"role":@"assistant",@"content":@"",@"tool_calls":@[@{@"id":@"p-1",@"name":@"create_file",@"arguments":@{@"content":Large(6000)}},@{@"id":@"p-2",@"name":@"create_file",@"arguments":@{@"content":Large(6000)}}]};NSArray *partialHistory=@[input[1],partial,@{@"role":@"tool",@"tool_call_id":@"p-1",@"content":@"Done"}];out=[TFAIContextProjection project:partialHistory schemas:schemas statistics:nil error:nil];Check([out[1][@"tool_calls"] isEqual:partial[@"tool_calls"]],@"incomplete parallel tool batch is never rewritten");
 NSDictionary *provider=@{@"role":@"assistant",@"content":@"",@"providerProtocol":@"responses",@"providerModel":@"fixture",@"providerConnectionID":@"fixture",@"provider_items":@[@{@"type":@"reasoning",@"id":@"reason-1",@"encrypted_content":@"opaque-original"}]};out=[TFAIContextProjection project:@[input[1],provider] schemas:schemas statistics:nil error:nil];Check([out[1][@"provider_items"] isEqual:provider[@"provider_items"]],@"opaque reasoning continuation left intact");
 NSUInteger sumBefore=0,sumAfter=0;for(NSUInteger n=1;n<=30;n++){[TFAIContextProjection project:Fixture(n,NO) schemas:schemas statistics:&stats error:nil];sumBefore+=[stats[@"beforeTextJSONBytes"] unsignedIntegerValue];sumAfter+=[stats[@"afterTextJSONBytes"] unsignedIntegerValue];}printf("SYNTHETIC_30_ROUNDS cumulative_before=%lu cumulative_after=%lu bytes (not current window or billed tokens)\n",sumBefore,sumAfter);
 printf("PASS %lu context projection checks\n",checks);
}return 0;}
